/** The description a host sees: the task-worded text, then the example calls. */
export function listedDescription(t: ToolDef): string {
  return t.description;
}

const VALIDATORS = new Map(TOOLS.map((t) => [t.name, z.fromJSONSchema(t.validation as never)]));
const ALIASES = new Set(ALIAS_NAMES);

export type ResolvedCall = { ok: true; tool: string } | { ok: false; reason: "invalid_arguments" | "unknown_tool"; message: string };

/** Do these arguments pass the named tool's input schema? A former action name passes as the monorepo's alias does. */
export function resolveToolCall(name: string, args: Record<string, unknown>): ResolvedCall {
  const v = VALIDATORS.get(name);
  if (v) {
    const parsed = v.safeParse(args);
    return parsed.success ? { ok: true, tool: name } : { ok: false, reason: "invalid_arguments", message: parsed.error.message };
  }
  if (ALIASES.has(name)) return { ok: true, tool: name };
  return { ok: false, reason: "unknown_tool", message: `no tool ${name}` };
}
